from math import exp
from itertools import combinations

def dsep(a,b,z,edges):
    parents={}; adj={}
    for u,v in edges:
        parents.setdefault(v,set()).add(u)
        adj.setdefault(u,set()).add(v); adj.setdefault(v,set()).add(u)
    anc=set(z); todo=list(z)
    while todo:
        for p in parents.get(todo.pop(),set()):
            if p not in anc: anc.add(p); todo.append(p)
    def active(path):
        for i in range(1,len(path)-1):
            l,v,r=path[i-1:i+2]
            collider=(l,v) in edges and (r,v) in edges
            if collider and v not in anc: return False
            if not collider and v in z: return False
        return True
    def paths(path):
        v=path[-1]
        if v==b: return active(path)
        return any(paths(path+[w]) for w in adj.get(v,set()) if w not in path)
    return not paths([a])

observed=['H','V','R','P']
# P denotes the predicted outcome; latent U and C expand bidirected edges.
g1={('U','H'),('U','V'),('H','R'),('C','R'),('C','P'),('V','P')}
g2={('H','V'),('V','P'),('H','R'),('C','R'),('C','P')}
def independences(edges):
    result=[]
    for a,b in combinations(observed,2):
        rest=[x for x in observed if x not in (a,b)]
        for n in range(len(rest)+1):
            for zs in combinations(rest,n):
                if dsep(a,b,set(zs),edges): result.append((a,b,zs))
    return result
print('Observed CI relations in latent expansion of Figure 4:',independences(g1))
print('Observed CI relations with H -> V -> prediction:',independences(g2))
print('Same CI relations:',independences(g1)==independences(g2))
sig=lambda x:1/(1+exp(-x))
