q1=(sig(2.0)+sig(3.75))/2
print('From stated simulation equations, P(Y=1 | H=0):',(q0+2*q1)/3)
print('From stated simulation equations, P(Y=1 | H=1):',(2*q0+q1)/3)
print('Sum of reported bird split sizes:',2849+520+529)
PY"
